def add_keys_to_file(filepath, lang_index):
    with open(filepath, 'r', encoding='utf-8') as f:
        content = f.read()
    
    lines = content.split('\n')
    insert_idx = None
    for i in range(len(lines) - 1, -1, -1):
        if 'preset.unseededKnockout.why' in lines[i]:
            insert_idx = i + 1
            break
    
    if insert_idx is None:
        print(f"Could not find insert point in {filepath}")
        return False
    
    new_lines = []
    new_lines.append('  // ---- sailing formats ---------------------------------------------------')
    for key, translations in keys:
        value = translations[lang_index]
        escaped_value = value.replace("'", "\\'").replace("\\", "\\\\")
        new_lines.append(f"  '{key}': '{escaped_value}',")
    
    new_content = '\n'.join(lines[:insert_idx]) + '\n' + '\n'.join(new_lines) + '\n' + '\n'.join(lines[insert_idx:])
    
    with open(filepath, 'w', encoding='utf-8') as f:
        f.write(new_content)
    
    print(f"Added {len(keys)} keys to {filepath}")
    return True

